#include "planning_document.hpp"
#include <algorithm>
#include <charconv>
#include <tora/core/number_parser.hpp>
#include <cmath>
#include <iomanip>
#include <sstream>
#include <stdexcept>
#include <vector>
namespace tora::desktop {
namespace {
void field(const std::string& s){if(s.find_first_of("\r\n\0",0,3)!=std::string::npos)throw std::invalid_argument("Planning fields must occupy one line.");}
std::string quote(const std::string& s){field(s);std::string r="\"";for(char c:s){r+=c;if(c=='\"')r+=c;}return r+'\"';}
std::string unquote(const std::string& s){if(s.size()<2||s.front()!='\"'||s.back()!='\"')throw std::invalid_argument("Expected a quoted planning field.");std::string r;for(std::size_t i=1;i+1<s.size();++i){if(s[i]=='\"'){if(i+2>=s.size()||s[i+1]!='\"')throw std::invalid_argument("Invalid planning field quoting.");++i;}r+=s[i];}field(r);return r;}
int integer(const std::string& s){int v=0;auto result=std::from_chars(s.data(),s.data()+s.size(),v);if(s.empty()||result.ec!=std::errc{}||result.ptr!=s.data()+s.size())throw std::invalid_argument("Invalid planning integer.");return v;}
double number(const std::string& s){double v=0;auto result=core::parseDouble(s.data(),s.data()+s.size(),v);if(s.empty()||result.ec!=std::errc{}||result.ptr!=s.data()+s.size()||!std::isfinite(v))throw std::invalid_argument("Planning durations must be finite numbers.");return v;}
std::string numeric(double v){std::ostringstream s;s<<std::setprecision(17)<<v;return s.str();}
bool same(const planning::Problem& a,const planning::Problem& b){if(a.method!=b.method||a.activities.size()!=b.activities.size())return false;for(std::size_t i=0;i<a.activities.size();++i){const auto& x=a.activities[i];const auto& y=b.activities[i];if(x.from!=y.from||x.to!=y.to||x.symbol!=y.symbol||x.duration!=y.duration||x.optimistic!=y.optimistic||x.mostLikely!=y.mostLikely||x.pessimistic!=y.pessimistic)return false;}return true;}
}
PlanningDocument PlanningDocument::create(std::string title,planning::Problem problem,core::NumberFormat format){PlanningDocument d;d.update(std::move(title),std::move(problem),format);return d;}
void PlanningDocument::update(std::string title,planning::Problem problem,core::NumberFormat format){field(title);if(title.size()>4000||problem.activities.size()>10000||(problem.method!=planning::Method::Cpm&&problem.method!=planning::Method::Pert))throw std::invalid_argument("Unsupported planning model size or method.");(void)core::NumberFormatter(format);for(const auto& a:problem.activities){field(a.symbol);if(a.from<1||a.to<1||a.symbol.size()>4000||!std::isfinite(a.duration)||!std::isfinite(a.optimistic)||!std::isfinite(a.mostLikely)||!std::isfinite(a.pessimistic))throw std::invalid_argument("Planning endpoints must be positive and estimates finite.");}if(title_!=title||!same(problem_,problem)||format.n!=format_.n||format.d!=format_.d||format.notation!=format_.notation)original_.clear();title_=std::move(title);problem_=std::move(problem);format_=format;}
PlanningDocument PlanningDocument::decode(std::string_view bytes){if(bytes.size()>4*1024*1024)throw std::invalid_argument("Planning file exceeds 4 MiB.");std::istringstream input{std::string(bytes)};std::vector<std::string> lines;for(std::string s;std::getline(input,s);){if(!s.empty()&&s.back()=='\r')s.pop_back();field(s);lines.push_back(std::move(s));}if(lines.size()<7)throw std::invalid_argument("Truncated planning header.");const int marker=integer(lines[0]);if(marker!=8001&&marker!=8002)throw std::invalid_argument("Expected an 8001 CPM or 8002 PERT file.");core::NumberFormat f;f.n=integer(lines[1]);f.d=integer(lines[2]);const int notation=integer(lines[3]);if(notation!=1&&notation!=2)throw std::invalid_argument("Invalid planning notation.");f.notation=notation==1?core::Notation::Decimal:core::Notation::Scientific;const int maxNode=integer(lines[5]),rows=integer(lines[6]);const std::size_t columns=marker==8001?4:6;if(maxNode<0||rows<1||rows>10002||lines.size()!=7+static_cast<std::size_t>(rows-1)*columns)throw std::invalid_argument("Planning row count does not match its records.");planning::Problem p;p.method=marker==8001?planning::Method::Cpm:planning::Method::Pert;int observedMax=0;for(int i=0;i<rows-1;++i){std::vector<std::string> v;for(std::size_t j=0;j<columns;++j)v.push_back(unquote(lines[7+static_cast<std::size_t>(i)*columns+j]));const bool blank=(v[0].empty()||v[0]=="0")&&std::all_of(v.begin()+1,v.end(),[](const auto& x){return x.empty();});if(blank)continue;planning::Activity a;a.from=integer(v[0]);a.to=integer(v[1]);a.symbol=v[2];if(p.method==planning::Method::Cpm)a.duration=number(v[3]);else{a.optimistic=number(v[3]);a.mostLikely=number(v[4]);a.pessimistic=number(v[5]);}observedMax=std::max({observedMax,a.from,a.to});p.activities.push_back(std::move(a));}if(observedMax>maxNode)throw std::invalid_argument("Planning event number exceeds the saved maximum.");auto d=create(unquote(lines[4]),std::move(p),f);d.original_=std::string(bytes);return d;}
std::string PlanningDocument::encode()const{if(!original_.empty())return original_;int maxNode=0;for(const auto& a:problem_.activities)maxNode=std::max({maxNode,a.from,a.to});std::ostringstream out;out<<(problem_.method==planning::Method::Cpm?8001:8002)<<"\r\n"<<format_.n<<"\r\n"<<format_.d<<"\r\n"<<(format_.notation==core::Notation::Decimal?1:2)<<"\r\n"<<quote(title_)<<"\r\n"<<maxNode<<"\r\n"<<problem_.activities.size()+1<<"\r\n";for(const auto& a:problem_.activities){out<<quote(std::to_string(a.from))<<"\r\n"<<quote(std::to_string(a.to))<<"\r\n"<<quote(a.symbol)<<"\r\n";if(problem_.method==planning::Method::Cpm)out<<quote(numeric(a.duration))<<"\r\n";else out<<quote(numeric(a.optimistic))<<"\r\n"<<quote(numeric(a.mostLikely))<<"\r\n"<<quote(numeric(a.pessimistic))<<"\r\n";}return out.str();}
}
